import groovy.lang.GroovyShell

// Initialize the shell to evaluate scripts
def shell = new GroovyShell()
// Define the dynamic rule logic as a script
def script = shell.parse('price * (1 - discountRate)')
// Bind variables to the script context
def result = script.evaluate([price: 100.0, discountRate: 0.1])
